create table nu_directory (
    nursing_unit_id   number
        generated by default on null as identity
    not null enable,
    fk_building_id    number,
    nurse_unit_disp   varchar2(4000 char),
    nurse_unit_desc   varchar2(4000 char),
    nu_outbound_alias varchar2(4000 char)
);

alter table nu_directory
    add constraint bldg_disp_id_pk primary key ( nursing_unit_id )
        using index enable;


